3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
9	
10	/**
11	 * Normalizes the optional owner {@code email}. Email may be omitted; when present it must
12	 * be a syntactically valid address. A valid address is stored lower-cased (so it is later
13	 * mapped onto the {@link org.springframework.samples.petclinic.model.Owner} and returned
14	 * lower-cased); a present-but-invalid address is rejected 400 via
15	 * {@link InvalidEmailException}. A blank value is treated as absent.
16	 *
17	 * <p>Mutates the published body in place, mirroring {@link NormalizeOwnerTelephone}.
18	 */
19	public class NormalizeOwnerEmail {
20	
21	    /**
22	     * Syntactic email check: a non-empty local part, an '@', then a domain with at least one
23	     * dot and non-empty labels, none of the parts containing whitespace or a second '@'.
24	     */
25	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@.]+(\\.[^\\s@.]+)+$");
26	
27	    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
28	        String email = request.getEmail();
29	        if (email == null || email.isBlank()) {
30	            request.setEmail(null);
31	            return;
32	        }
33	        String trimmed = email.trim();
34	        if (!EMAIL.matcher(trimmed).matches()) {
35	            throw new InvalidEmailException("Email must be a syntactically valid address");
36	        }
37	        request.setEmail(trimmed.toLowerCase(Locale.ROOT));
38	    }
39	}
